(function(){
  'use strict';
  const api='../../../api/vendor/';
  const state={csrf:'',orders:[],current:null};
  const money=new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'});
  const steps={awaiting_acceptance:['accepted','Accept order'],accepted:['processing','Start processing'],processing:['quality_check','Quality check complete'],quality_check:['packing','Start packing'],packing:['ready_to_dispatch','Ready to dispatch']};
  function node(tag,cls,value){const item=document.createElement(tag);if(cls)item.className=cls;if(value!==undefined)item.textContent=String(value);return item;}
  function label(value){return String(value||'').replaceAll('_',' ');}
  function notice(value,error=false){const box=document.getElementById('orders-message');box.hidden=false;box.textContent=value;box.classList.toggle('cat-error',error);box.scrollIntoView({block:'nearest'});}
  async function call(path,method='GET',body){const headers={Accept:'application/json'};if(method!=='GET')headers['X-CSRF-Token']=state.csrf;if(body!==undefined)headers['Content-Type']='application/json';const response=await fetch(api+path,{method,credentials:'same-origin',cache:'no-store',headers,body:body===undefined?undefined:JSON.stringify(body)});const result=await response.json().catch(()=>({}));if(!response.ok)throw Error(result.message||'Unable to complete this action.');return result;}
  async function load(){const result=await call('orders.php');state.orders=result.orders||[];document.getElementById('order-count-awaiting').textContent=state.orders.filter(order=>order.status==='awaiting_acceptance').length;document.getElementById('order-count-preparing').textContent=state.orders.filter(order=>['accepted','processing','quality_check','packing'].includes(order.status)).length;document.getElementById('order-count-ready').textContent=state.orders.filter(order=>order.status==='ready_to_dispatch').length;document.getElementById('order-count-delivery').textContent=state.orders.filter(order=>['partially_dispatched','dispatched','in_transit','delivery_exception'].includes(order.status)).length;render();}
  function render(){const target=document.getElementById('orders-list');target.replaceChildren();const query=document.getElementById('orders-search').value.trim().toLowerCase();const filter=document.getElementById('orders-filter').value;const matching=state.orders.filter(order=>(!filter||order.status===filter)&&(!query||String(order.group_number).toLowerCase().includes(query)||String(order.order_number).toLowerCase().includes(query)));if(!matching.length){target.append(node('p','vc-help',state.orders.length?'No orders match this filter.':'No real customer orders for this vendor yet.'));return;}matching.forEach(order=>{const row=node('div','cat-row');const info=node('div');info.append(node('strong','',order.group_number),node('small','',label(order.status)+' · '+order.item_count+' item(s) · '+money.format(Number(order.total_amount))+' · '+label(order.payment_status)));const button=node('button','vc-btn small','Open');button.type='button';button.addEventListener('click',()=>open(order.id).catch(error=>notice(error.message,true)));row.append(info,button);target.append(row);});}
  async function open(id){const result=await call('orders.php?id='+encodeURIComponent(id));const order=result.order;state.current=order;document.getElementById('orders-detail').hidden=false;document.getElementById('orders-detail-title').textContent=order.group_number;document.getElementById('orders-detail-status').textContent=label(order.status);const items=document.getElementById('orders-detail-items');items.replaceChildren();(order.items||[]).forEach(product=>items.append(node('p','',product.product_name+' · '+product.quantity+' × '+money.format(Number(product.unit_price)))));document.getElementById('orders-detail-money').textContent='Products '+money.format(Number(order.subtotal))+' · Delivery '+money.format(Number(order.shipping_amount))+' · Total '+money.format(Number(order.total_amount))+' · Payment '+label(order.payment_status);const address=order.address||{};document.getElementById('orders-detail-address').textContent=[address.full_name,address.address_line1,address.address_line2,address.city,address.state,address.pincode].filter(Boolean).join(', ');const actions=document.getElementById('orders-detail-actions');actions.replaceChildren();const step=steps[order.status];if(step){const button=node('button','vc-btn primary',step[1]);button.type='button';button.addEventListener('click',()=>update(order.id,step[0],button));actions.append(button);}if(['awaiting_acceptance','accepted','processing'].includes(order.status)){const button=node('button','vc-btn danger',order.status==='awaiting_acceptance'?'Reject order':'Cancel order');button.type='button';button.addEventListener('click',()=>{const reason=prompt('Enter a detailed reason (at least 10 characters). This action affects the customer.');if(reason===null)return;if(reason.trim().length<10){notice('Please provide at least 10 characters.',true);return;}update(order.id,order.status==='awaiting_acceptance'?'rejected':'cancelled',button,reason.trim());});actions.append(button);}const delivery=node('a','vc-btn','Manage delivery');delivery.href='delivery.php?order='+encodeURIComponent(order.id);actions.append(delivery);document.getElementById('orders-detail').scrollIntoView({block:'start'});}
  async function update(id,status,button,reason=''){button.disabled=true;try{const result=await call('orders.php','POST',{group_id:id,status,reason});notice(result.message);await load();await open(id);}catch(error){notice(error.message,true);button.disabled=false;}}
  document.getElementById('orders-refresh').addEventListener('click',()=>load().catch(error=>notice(error.message,true)));
  document.getElementById('orders-search').addEventListener('input',render);
  document.getElementById('orders-filter').addEventListener('change',render);
  (async()=>{try{const identity=await call('auth/me.php');state.csrf=identity.csrf_token;await load();}catch(error){notice(error.message,true);}})();
})();
